data.query:
query Query($whereSO: SalesOrderWhereInput, $whereLines: SalesOrderLineWhereInput) {
  salesOrder(where: $whereSO first: 1) {
    edges {
      node {
        id
        number
        facilityId
        lines(where: $whereLines) {
        edges {
            node {
              id productId quantity {value unitId}
            }
          }
        }

      }
    }
  }
}

data.variablesTransform:
(

$s := $state.context.LOCAL.salesOrder;
$id := $cuid();
{
  "payload": {
    "create": {
      "id": $id,
      "loadId": $state.context.REQUEST.DATA.load.id,
      "salesOrderId": $s.id,
      "shipmentTypeId": "Customer Shipment",
      "shipmentStageId": "New",
      "scheduledShipAt": $state.context.REQUEST.DATA.load.scheduledAt,
      "shipFromFacilityId": $state.context.REQUEST.DATA.load.location.facilityId
    }
  },

  "payloadL": $state.context.LOCAL.salesOrder.lines.edges.node.{
    "create":{
      "shipmentId": $id,
      "salesOrderLineId": id,
      "stagedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
      "loadedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
      "shippedQuantity":  {
        "value": 0,
        "unitId": quantity.unitId
      },
      "quantity":quantity,
      "shipmentLineStageId": "New",
      "productId": productId
    }
  }
}

)

data.query:
query Query($where: ShipmentLineWhereInput, $orderBy: [ShipmentLineOrderByInput!], $first: Int, $after: String) {
  lines:shipmentLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
      }
    }
  }
}

query Query($whereTO: TransferOrderWhereInput, $whereLines: TransferOrderLineWhereInput) {

  transferOrder(where: $whereTO, first:1){
    edges {
      node {
        id 
        number
        fromFacilityId
        toFacilityId
        subsidiaryId
        transferOrderLines (where: $whereLines){
          edges {
            node {
              id
              productId
              transferQuantity {value unitId}

            }
          }
        }
      }
    }
  }
}

